function scheduleBot(){botThinking=true;statusEl.textContent=`${mode==='tournament'?tournamentOpponents[tournamentRound].name:'DIO'} está pensando...`;boardEl.classList.add('thinking');setTimeout(()=>{if(gameOver||mode==='local'||turn!=='b'){botThinking=false;boardEl.classList.remove('thinking');return}botThinking=false;boardEl.classList.remove('thinking');const powerAction=useVillainPower();if(powerAction==='spent')return;const move=chooseBotMove();if(move)makeMove(move.from,move.to,move.promotion||'q')},450)}
function updateStatus(){document.querySelector('#power-label').textContent=isTwoPlayerMode()?'PODER DE '+sideDisplayName(turn).toLocaleUpperCase():turn==='w'?'PODER DE JOTARO':'PODER DO VILÃO';const activePower=isTwoPlayerMode()?localPowers[turn]:equippedPower;if(loveTrainRemaining>0&&turn!==loveTrainOwner&&(activePower==='hamon'||activePower==='killer'))powerButton.disabled=true;if(gameOver)return;const check=inCheck(board,turn),opponent=sideDisplayName('b');statusEl.textContent=!canPlayTurn()?mode==='multiplayer'?(multiplayerGuestJoined?'Aguardando '+sideDisplayName(turn)+' jogar...':'Aguardando o segundo jogador entrar...'):opponent+' está pensando...':pendingPower==='hamon'?'Onda Hamon: escolha um peão inimigo no tabuleiro.':pendingPower==='killer'?'Killer Queen: escolha uma peça inimiga para explodir.':pendingPower==='arrow'?'Flecha do Stand: escolha um peão seu no tabuleiro.':pendingPower==='diamond'?'Crazy Diamond: escolha uma casa vazia para restaurar '+names[type(pendingRestorePiece)]+'.':(extraTurn?'TEMPO PARADO · ':'')+'A vez de '+sideDisplayName(turn)+(check?' · XEQUE':'');if(loveTrainRemaining>0&&turn!==loveTrainOwner)statusEl.textContent+=' · LOVE TRAIN: '+loveTrainRemaining+' turno(s) de proteção';statusEl.classList.toggle('check',check)}
function renderLog(){moveList.innerHTML='';if(!history.length){moveList.innerHTML='<li class="empty">A aventura começa...</li>';return}history.slice(-8).forEach((h,i)=>{const n=history.length-Math.min(history.length,8)+i+1,li=document.createElement('li'),number=document.createElement('span');number.textContent=`${n}.`;li.append(number,document.createTextNode(`${sideDisplayName(h.piece[0])} · ${names[type(h.piece)]}${h.captured?' ✕ '+names[type(h.captured)]:''}`));moveList.appendChild(li)})}
function renderCaptures(){const list=captured.w;if(!list.length){captureEl.className='capture-list empty';captureEl.textContent='Nenhuma peça capturada';return}captureEl.className='capture-list';captureEl.textContent=list.map(p=>glyph[p]).join(' ')}
function renderBracket(){const card=document.querySelector('#tournament-card'),list=document.querySelector('#bracket');card.hidden=mode!=='tournament';if(mode!=='tournament')return;list.innerHTML='';tournamentOpponents.forEach((opponent,index)=>{const item=document.createElement('li');item.className=index<tournamentRound?'done':index===tournamentRound?'current':'upcoming';item.textContent=`${index+1}. ${opponent.name}${index<tournamentRound?' · VENCIDO':index===tournamentRound?' · AGORA':''}${ownedPowers.includes(powerOrder[index])?' · PODER LIBERADO':''}`;list.appendChild(item)})}
function loadProfile(){try{const saved=JSON.parse(localStorage.getItem(accountStorageKey('profile'))||'{}');coins=Math.max(0,Number(saved.coins)||0);ownedPowers=Array.isArray(saved.unlockedPowers)?powerOrder.filter(power=>saved.unlockedPowers.includes(power)):[];equippedPower=ownedPowers.includes(saved.equippedPower)?saved.equippedPower:(ownedPowers[0]||null);profileCharacter=characterPhotos[saved.profileCharacter]?saved.profileCharacter:'jotaro'}catch{coins=0;ownedPowers=[];equippedPower=null;profileCharacter='jotaro'}if(isAdminAccount()){coins=ADMIN_COIN_BALANCE;ownedPowers=powerOrder.slice();equippedPower=powerOrder.includes(equippedPower)?equippedPower:powerOrder[0]}}
function saveProfile(){if(isAdminAccount()){coins=ADMIN_COIN_BALANCE;ownedPowers=powerOrder.slice();if(!powerOrder.includes(equippedPower))equippedPower=powerOrder[0]}const profile={coins,unlockedPowers:ownedPowers,equippedPower,profileCharacter,savedAt:Date.now()};try{localStorage.setItem(accountStorageKey('profile'),JSON.stringify(profile))}catch{}queueSave(accountDatabaseKey('profile'),profile);queueServerState({profile})}
function updateCoinDisplay(){const balance=isAdminAccount()?'∞':String(coins);document.querySelector('#coins-menu').textContent=balance;document.querySelector('#coins-game').textContent=balance;document.querySelector('#coins-shop').textContent=balance;document.querySelector('#menu-equipped').textContent=(powerInfo[equippedPower]?.title||'Nenhum poder');document.querySelector('#signed-in-as').textContent=currentUser?`Conta: ${currentUser.username}${isAdminAccount()?' · ADMIN':''}`:'';document.querySelector('#open-local-admin').hidden=currentUser?.role!=='admin';document.querySelector('#admin-code-input').disabled=!currentUser;document.querySelector('#activate-admin').disabled=!currentUser}
function renderShop(){
  const list=document.querySelector('#shop-items');
  list.replaceChildren();
  for(const [index,id] of powerOrder.entries()){
    const power=powerInfo[id],owned=ownedPowers.includes(id),equipped=equippedPower===id;
    const card=document.createElement('article');
    card.className=`shop-item${owned?' is-unlocked':''}${equipped?' is-equipped':''}`;
    const icon=document.createElement('span');icon.className='shop-item-icon';icon.innerHTML=powerIconSvg(id);icon.setAttribute('aria-hidden','true');
    const details=document.createElement('div');details.className='shop-item-details';
    const title=document.createElement('strong');title.className='shop-power-title';title.textContent=power.title;
    const character=document.createElement('span');character.className='shop-character';character.textContent=power.character;
    const description=document.createElement('p');description.className='shop-power-description';description.textContent=power.description;
    const recharge=document.createElement('span');recharge.className='shop-recharge';recharge.textContent='Recarga: 3 turnos';
    details.append(title,character,description,recharge);
    const controls=document.createElement('div');controls.className='shop-item-controls';
    const badge=document.createElement('span');badge.className=`shop-state${equipped?' equipped':owned?' unlocked':' locked'}`;
    badge.textContent=equipped?'EM USO':owned?'LIBERADO':`TORNEIO · FASE ${index+1}`;
    controls.append(badge);
    const button=document.createElement('button');button.className='shop-buy';button.disabled=!owned||equipped;button.textContent=equipped?'EQUIPADO':owned?'EQUIPAR':'BLOQUEADO';
    if(owned&&!equipped)button.addEventListener('click',()=>{equippedPower=id;saveProfile();updateCoinDisplay();renderShop();render()});
    controls.append(button);card.append(icon,details,controls);list.appendChild(card);
  }
}
function openShop(){renderShop();const dialog=document.querySelector('#shop-dialog');if(!dialog.open)dialog.showModal()}
function currentMatchSnapshot(){return{version:1,savedAt:Date.now(),mode,gameOver,resultText:gameOver?statusEl.textContent:'',board:board.map(row=>row.slice()),turn,castlingRights:JSON.parse(JSON.stringify(castlingRights)),enPassantTarget:enPassantTarget?enPassantTarget.slice():null,halfmoveClock,repetitionCounts:{...repetitionCounts},history:history.map(item=>({...item,from:item.from.slice(),to:item.to.slice(),boardBefore:item.boardBefore?{...item.boardBefore,board:item.boardBefore.board.map(row=>row.slice()),rights:JSON.parse(JSON.stringify(item.boardBefore.rights)),ep:item.boardBefore.ep?item.boardBefore.ep.slice():null,repetitions:{...item.boardBefore.repetitions}}:null})),captured:{w:captured.w.slice(),b:captured.b.slice()},usedPower:{w:{...usedPower.w},b:{...usedPower.b}},extraTurn,pendingPower,pendingRestorePiece,loveTrainRemaining,loveTrainOwner,loveTrainUsed,localPowers:{...localPowers},tournamentRound,tournamentRewarded,playerNames:{...playerNames},playerCharacters:{...playerCharacters},lastMove:lastMove?{from:lastMove.from.slice(),to:lastMove.to.slice()}:null,equippedPower,tournamentResultWon,tournamentResultPending}}
function saveCurrentMatch(){if(mode==='multiplayer'){if(currentUser&&multiplayerConnection?.open&&!multiplayerApplyingState&&!document.querySelector('#game').hidden)syncMultiplayerSnapshot(currentMatchSnapshot());return}if(!currentUser||document.querySelector('#game').hidden)return;if(gameOver){try{localStorage.removeItem(accountStorageKey('activeMatch'))}catch{}queueSave(accountDatabaseKey('activeMatch'),null,true);queueServerState({activeMatch:null});return}const snapshot=currentMatchSnapshot();try{localStorage.setItem(accountStorageKey('activeMatch'),JSON.stringify(snapshot))}catch{}queueSave(accountDatabaseKey('activeMatch'),snapshot);queueServerState({activeMatch:snapshot})}
function updateMultiplayerRoomInfo(){const info=document.querySelector('#multiplayer-room-info');info.hidden=mode!=='multiplayer';document.querySelector('#multiplayer-room-code').textContent=multiplayerRoomCode||'—';const restartButton=document.querySelector('#multiplayer-restart');restartButton.disabled=!multiplayerConnection?.open||!multiplayerGuestJoined||multiplayerRestartRequested;restartButton.textContent=multiplayerRestartRequested?'REINÍCIO SOLICITADO · AGUARDANDO':multiplayerRemoteRestartRequested?'CONFIRMAR REINÍCIO':'↻  PEDIR REINÍCIO · AMBOS CONFIRMAM';if(multiplayerRestartRequested||multiplayerRemoteRestartRequested){updateMultiplayerRestartStatus();return}document.querySelector('#multiplayer-room-status').textContent=!multiplayerGuestJoined?'Aguardando o jogador 2 entrar':canPlayTurn()?'Sua vez de jogar':'Aguardando '+sideDisplayName(turn)+' jogar'}
function closeMultiplayerPeer(){if(multiplayerRestartTimer){clearTimeout(multiplayerRestartTimer);multiplayerRestartTimer=null}const connection=multiplayerConnection,peer=multiplayerPeer;multiplayerConnection=null;multiplayerPeer=null;if(connection)connection.close();if(peer)peer.destroy()}
function makeRoomCode(){const alphabet='23456789ABCDEFGHJKLMNPQRSTUVWXYZ';const bytes=crypto.getRandomValues(new Uint8Array(6));return Array.from(bytes,value=>alphabet[value%alphabet.length]).join('')}
function openMultiplayerPeer(id){return new Promise((resolve,reject)=>{if(!window.Peer){reject(new Error('A biblioteca de conexão não carregou. Atualize a página e tente novamente.'));return}const peer=id?new Peer(id,{debug:1}):new Peer({debug:1});multiplayerPeer=peer;let settled=false;const timeout=setTimeout(()=>{if(!settled){settled=true;peer.destroy();reject(new Error('A conexão com o serviço de salas expirou. Confira sua internet e tente novamente.'))}},15000);peer.on('open',()=>{if(settled)return;settled=true;clearTimeout(timeout);resolve(peer)});peer.on('error',error=>{if(!settled){settled=true;clearTimeout(timeout);peer.destroy();reject(error)}else if(mode==='multiplayer'){const status=document.querySelector('#multiplayer-room-status');if(status)status.textContent='Conexão interrompida · reconecte à sala'}})})}
function bindMultiplayerConnection(connection){multiplayerConnection=connection;connection.on('data',message=>handleMultiplayerMessage(message));connection.on('close',()=>{if(multiplayerConnection!==connection)return;multiplayerConnection=null;multiplayerGuestJoined=false;updateMultiplayerRoomInfo();const status=document.querySelector('#multiplayer-room-status');if(status)status.textContent='Conexão encerrada · atualize a sala para reconectar'});connection.on('error',()=>{const status=document.querySelector('#multiplayer-room-status');if(status)status.textContent='Falha na conexão direta entre os jogadores'})}
function sendMultiplayerState(snapshot=currentMatchSnapshot()){if(!multiplayerConnection?.open)return;multiplayerConnection.send({type:'state',revision:++multiplayerRevision,state:snapshot})}
function clearMultiplayerRestartVote(){if(multiplayerRestartTimer){clearTimeout(multiplayerRestartTimer);multiplayerRestartTimer=null}multiplayerRestartRequested=false;multiplayerRemoteRestartRequested=false;const button=document.querySelector('#multiplayer-restart');if(button)button.disabled=false}
function updateMultiplayerRestartStatus(){const status=document.querySelector('#multiplayer-room-status');if(!status)return;status.textContent=multiplayerRestartRequested&&multiplayerRemoteRestartRequested?'Os dois confirmaram · reiniciando…':multiplayerRestartRequested?'Você confirmou · aguardando o outro jogador (20 s)':multiplayerRemoteRestartRequested?'O outro jogador confirmou · confirme também (20 s)':''}
function restartMultiplayerRound(){if(multiplayerSeat!=='w'||!multiplayerRestartRequested||!multiplayerRemoteRestartRequested)return;clearMultiplayerRestartVote();multiplayerApplyingState=true;resetRound();multiplayerApplyingState=false;updateOpponent();render();renderLog();renderCaptures();if(multiplayerConnection?.open)multiplayerConnection.send({type:'restart-state',revision:++multiplayerRevision,state:currentMatchSnapshot()});updateMultiplayerRoomInfo()}
function requestMultiplayerRestart(){if(!multiplayerConnection?.open||!multiplayerGuestJoined)return;if(multiplayerRestartRequested)return;multiplayerRestartRequested=true;const button=document.querySelector('#multiplayer-restart');button.disabled=true;multiplayerConnection.send({type:'restart-request',requested:true});updateMultiplayerRestartStatus();multiplayerRestartTimer=setTimeout(()=>leaveMultiplayerToMenu(true),20000);restartMultiplayerRound()}
function leaveMultiplayerToMenu(notifyPeer=false){if(notifyPeer&&multiplayerConnection?.open)multiplayerConnection.send({type:'exit-room'});clearMultiplayerRestartVote();closeMultiplayerPeer();multiplayerRoomCode=null;multiplayerSeat=null;multiplayerGuestJoined=false;document.querySelector('#game').hidden=true;document.querySelector('#game-menu').hidden=false;document.querySelector('#multiplayer-room-info').hidden=true}
function handleMultiplayerMessage(message){if(!message||typeof message!=='object')return;if(message.type==='exit-room'){leaveMultiplayerToMenu(false);return}if(message.type==='restart-request'){multiplayerRemoteRestartRequested=!!message.requested;if(multiplayerRemoteRestartRequested&&!multiplayerRestartTimer)multiplayerRestartTimer=setTimeout(()=>leaveMultiplayerToMenu(true),20000);updateMultiplayerRoomInfo();restartMultiplayerRound();return}if(message.type==='restart-state'&&multiplayerSeat==='b'&&message.state){clearMultiplayerRestartVote();multiplayerApplyingState=true;const restored=restoreSavedMatch(message.state);multiplayerApplyingState=false;if(restored){multiplayerReceivedRevision=message.revision||multiplayerReceivedRevision;updateMultiplayerRoomInfo()}return}if(message.type==='join'&&multiplayerSeat==='w'&&!multiplayerGuestJoined){const safeName=String(message.username||'Jogador 2').replace(/[^A-Za-z0-9 _-]/g,'').trim().slice(0,24)||'Jogador 2',character=characterPhotos[message.character]?message.character:'jolyne';multiplayerGuestJoined=true;playerNames.b=safeName;playerCharacters.b=character;updateOpponent();render();sendMultiplayerState();updateMultiplayerRoomInfo();return}if(message.type!=='state'||!message.state||!Number.isInteger(message.revision)||message.revision<=multiplayerReceivedRevision)return;const remoteSide=multiplayerSeat==='w'?'b':'w';if(multiplayerGuestJoined&&turn!==remoteSide){const status=document.querySelector('#multiplayer-room-status');if(status)status.textContent='Atualização fora de turno ignorada';return}multiplayerReceivedRevision=message.revision;multiplayerGuestJoined=true;multiplayerApplyingState=true;const restored=restoreSavedMatch(message.state);multiplayerApplyingState=false;if(!restored)return;updateMultiplayerRoomInfo();if(gameOver&&!document.querySelector('#result-overlay').open)showGameResult(message.state.resultText||'PARTIDA ENCERRADA');if(multiplayerSeat==='b'&&multiplayerJoinResolve){multiplayerJoinResolve();multiplayerJoinResolve=null;multiplayerJoinReject=null}}
function syncMultiplayerSnapshot(snapshot){if(multiplayerGuestJoined&&!multiplayerApplyingState)sendMultiplayerState(snapshot)}
async function createMultiplayerRoom(){if(!currentUser)throw new Error('Entre na sua conta antes de criar uma sala.');closeMultiplayerPeer();multiplayerRoomCode=null;multiplayerSeat='w';multiplayerRevision=0;multiplayerReceivedRevision=0;multiplayerGuestJoined=false;multiplayerRestartRequested=false;multiplayerRemoteRestartRequested=false;playerNames={w:currentUser.username,b:'Aguardando jogador 2'};playerCharacters={w:document.querySelector('#player-one-character').value,b:document.querySelector('#player-two-character').value};setMode('multiplayer');document.querySelector('#game-menu').hidden=true;document.querySelector('#game').hidden=false;let peer,error;for(let attempt=0;attempt<5;attempt++){try{peer=await openMultiplayerPeer(makeRoomCode());break}catch(caught){error=caught;if(caught.type!=='unavailable-id')throw caught}}if(!peer)throw error||new Error('Não foi possível reservar um código de sala.');multiplayerRoomCode=peer.id;peer.on('connection',connection=>{if(multiplayerGuestJoined||multiplayerConnection){connection.close();return}bindMultiplayerConnection(connection);connection.on('open',()=>{const status=document.querySelector('#multiplayer-room-status');if(status)status.textContent='Jogador conectado · preparando partida'})});updateMultiplayerRoomInfo();document.querySelector('#multiplayer-dialog').close();render()}
async function joinMultiplayerRoom(code){if(!currentUser)throw new Error('Entre na sua conta antes de entrar em uma sala.');if(!/^[A-Z0-9]{6}$/.test(code))throw new Error('O código precisa ter seis letras ou números.');closeMultiplayerPeer();multiplayerRoomCode=code;multiplayerSeat='b';multiplayerRevision=0;multiplayerReceivedRevision=0;multiplayerGuestJoined=false;multiplayerRestartRequested=false;multiplayerRemoteRestartRequested=false;playerNames={w:'Jogador 1',b:currentUser.username};playerCharacters.b=document.querySelector('#player-two-character').value;const peer=await openMultiplayerPeer();const connection=peer.connect(code,{reliable:true,serialization:'json'});bindMultiplayerConnection(connection);await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{multiplayerJoinResolve=null;multiplayerJoinReject=null;reject(new Error('Não foi possível entrar. Confira o código e se a sala ainda está aberta.'))},20000);multiplayerJoinResolve=()=>{clearTimeout(timeout);resolve()};multiplayerJoinReject=error=>{clearTimeout(timeout);reject(error)};connection.on('open',()=>connection.send({type:'join',username:currentUser.username,character:playerCharacters.b}))});updateMultiplayerRoomInfo();document.querySelector('#multiplayer-dialog').close()}

function restoreSavedMatch(saved){if(!saved||saved.version!==1||!['bot','local','multiplayer','tournament'].includes(saved.mode)||!Array.isArray(saved.board)||saved.board.length!==8||saved.board.some(row=>!Array.isArray(row)||row.length!==8)||!['w','b'].includes(saved.turn))return false;playerNames={w:saved.playerNames?.w||'Jogador 1',b:saved.playerNames?.b||'Jogador 2'};playerCharacters={w:characterPhotos[saved.playerCharacters?.w]?saved.playerCharacters.w:'jotaro',b:characterPhotos[saved.playerCharacters?.b]?saved.playerCharacters.b:'jolyne'};setMode(saved.mode);board=saved.board.map(row=>row.slice());turn=saved.turn;castlingRights=saved.castlingRights||{w:{k:true,q:true},b:{k:true,q:true}};enPassantTarget=saved.enPassantTarget||null;halfmoveClock=Number(saved.halfmoveClock)||0;repetitionCounts=saved.repetitionCounts||{};history=Array.isArray(saved.history)?saved.history:[];captured=saved.captured||{w:[],b:[]};usedPower=saved.usedPower||{w:{},b:{}};extraTurn=!!saved.extraTurn;pendingPower=saved.pendingPower||null;pendingRestorePiece=saved.pendingRestorePiece||null;loveTrainRemaining=Number(saved.loveTrainRemaining)||0;loveTrainOwner=saved.loveTrainOwner||null;loveTrainUsed=!!saved.loveTrainUsed;localPowers=saved.localPowers||{w:null,b:null};tournamentRound=Math.min(tournamentOpponents.length-1,Math.max(0,Number(saved.tournamentRound)||0));tournamentRewarded=!!saved.tournamentRewarded;tournamentResultWon=!!saved.tournamentResultWon;tournamentResultPending=!!saved.tournamentResultPending;equippedPower=ownedPowers.includes(saved.equippedPower)?saved.equippedPower:equippedPower;gameOver=!!saved.gameOver;selected=null;legal=[];lastMove=saved.lastMove|| (history.length?{from:history[history.length-1].from,to:history[history.length-1].to}:null);document.querySelector('#game-menu').hidden=true;document.querySelector('#game').hidden=false;if(tournamentResultPending){const next=document.querySelector('#tournament-next');next.hidden=false;next.textContent=tournamentResultWon?(tournamentRound===tournamentOpponents.length-1?'CONCLUIR TORNEIO':'AVANÇAR NO TORNEIO'):'TENTAR ESTA FASE DE NOVO'}updateOpponent();render();renderLog();renderCaptures();if(['bot','tournament'].includes(mode)&&turn==='b')scheduleBot();return true}
async function initializeSavedGame(accountState={}){
  document.querySelectorAll('[data-start-mode]').forEach(button=>button.disabled=true);
  const readLocal=key=>{try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}};
  const oldProfile=readLocal('jojoChessProfile'),scopedProfile=readLocal(accountStorageKey('profile'));
  const oldMatch=readLocal('jojoChessActiveMatch'),scopedMatch=readLocal(accountStorageKey('activeMatch'));
  let oldDbProfile=null,scopedDbProfile=null,oldDbMatch=null,scopedDbMatch=null;
  [oldDbProfile,scopedDbProfile,oldDbMatch,scopedDbMatch]=await Promise.all([
    readSavedValue('profile').catch(()=>null),readSavedValue(accountDatabaseKey('profile')).catch(()=>null),
    readSavedValue('activeMatch').catch(()=>null),readSavedValue(accountDatabaseKey('activeMatch')).catch(()=>null)
  ]);
  const latest=values=>values.filter(value=>value&&typeof value==='object').reduce((best,value)=>!best||(value.savedAt||0)>=(best.savedAt||0)?value:best,null);
  const profile=latest([oldProfile,oldDbProfile,scopedProfile,scopedDbProfile,accountState.profile]);
  const match=latest([oldMatch,oldDbMatch,scopedMatch,scopedDbMatch,accountState.activeMatch]);
  if(profile){try{localStorage.setItem(accountStorageKey('profile'),JSON.stringify(profile))}catch{}}
  if(match){try{localStorage.setItem(accountStorageKey('activeMatch'),JSON.stringify(match))}catch{}queueSave(accountDatabaseKey('activeMatch'),match)}
  try{localStorage.removeItem('jojoChessProfile');localStorage.removeItem('jojoChessActiveMatch')}catch{}
  queueSave('profile',null,true);queueSave('activeMatch',null,true);
  loadProfile();document.querySelector('#player-one-character').value=profileCharacter;saveProfile();updateCoinDisplay();renderShop();
  if(!restoreSavedMatch(match))resetRound();else saveCurrentMatch();
  document.querySelectorAll('[data-start-mode]').forEach(button=>button.disabled=false);
}
function resetRound(){stopPowerSounds();loveTrainRemaining=0;loveTrainOwner=null;loveTrainUsed=false;localPowers={w:null,b:null};if(isTwoPlayerMode()){const pool=powerOrder.slice();for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}localPowers={w:pool[0],b:pool[1]}}board=initial();turn='w';castlingRights={w:{k:true,q:true},b:{k:true,q:true}};enPassantTarget=null;halfmoveClock=0;repetitionCounts={};repetitionCounts[positionKey()]=1;promotionPending=null;pendingRestorePiece=null;selected=null;legal=[];lastMove=null;history=[];captured={w:[],b:[]};usedPower={w:{},b:{}};extraTurn=false;gameOver=false;botThinking=false;pendingPower=null;if(document.querySelector('#result-overlay').open)document.querySelector('#result-overlay').close();document.querySelector('#tournament-next').hidden=true;document.querySelector('#claim-draw').hidden=true;boardEl.classList.remove('thinking');render();renderLog();renderCaptures();renderBracket()}
