document.querySelector('#open-profile').addEventListener('click',()=>{document.querySelector('#profile-character').value=profileCharacter;updateProfilePhotoPreview();document.querySelector('#profile-dialog').showModal()});document.querySelector('#profile-character').addEventListener('change',updateProfilePhotoPreview);document.querySelector('#save-profile-photo').addEventListener('click',()=>{profileCharacter=document.querySelector('#profile-character').value;document.querySelector('#player-one-character').value=profileCharacter;playerCharacters.w=profileCharacter;saveProfile();document.querySelector('#profile-dialog').close()});document.querySelector('#close-profile').addEventListener('click',()=>document.querySelector('#profile-dialog').close());document.querySelector('#open-local-players').addEventListener('click',()=>document.querySelector('#local-players-dialog').showModal());document.querySelector('#close-local-players').addEventListener('click',()=>document.querySelector('#local-players-dialog').close());
document.querySelector('#bot-mode').addEventListener('click',()=>setMode('bot'));document.querySelector('#local-mode').addEventListener('click',()=>setMode('local'));document.querySelector('#tournament-mode').addEventListener('click',()=>setMode('tournament'));
document.querySelector('#open-multiplayer').addEventListener('click',()=>{document.querySelector('#multiplayer-message').textContent='';document.querySelector('#multiplayer-dialog').showModal()});document.querySelector('#close-multiplayer').addEventListener('click',()=>document.querySelector('#multiplayer-dialog').close());document.querySelector('#multiplayer-restart').addEventListener('click',requestMultiplayerRestart);document.querySelector('#multiplayer-code-input').addEventListener('input',event=>{event.currentTarget.value=event.currentTarget.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,6)});document.querySelector('#create-multiplayer-room').addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;document.querySelector('#multiplayer-message').textContent='Criando sala…';try{await createMultiplayerRoom()}catch(error){document.querySelector('#multiplayer-message').textContent=error.message}finally{button.disabled=false}});document.querySelector('#join-multiplayer-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;document.querySelector('#multiplayer-message').textContent='Procurando sala…';try{await joinMultiplayerRoom(document.querySelector('#multiplayer-code-input').value.trim().toUpperCase())}catch(error){document.querySelector('#multiplayer-message').textContent=error.message}finally{button.disabled=false}});document.querySelector('#copy-multiplayer-code').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(multiplayerRoomCode);document.querySelector('#multiplayer-room-status').textContent='Código copiado · compartilhe com o outro jogador'}catch{document.querySelector('#multiplayer-room-status').textContent='Código da sala: '+multiplayerRoomCode}});
function readPlayerNames(){const first=document.querySelector('#player-one-name-input').value.trim().slice(0,24)||currentUser?.username||'Jogador 1',second=document.querySelector('#player-two-name-input').value.trim().slice(0,24);playerNames={w:first||'Jogador 1',b:second||'Jogador 2'};playerCharacters={w:document.querySelector('#player-one-character').value,b:document.querySelector('#player-two-character').value}}
document.querySelectorAll('[data-start-mode]').forEach(button=>button.addEventListener('click',()=>{readPlayerNames();setMode(button.dataset.startMode);document.querySelector('#game-menu').hidden=true;document.querySelector('#game').hidden=false;saveCurrentMatch()}));
document.querySelector('#back-menu').addEventListener('click',()=>{stopPowerSounds();if(mode==='multiplayer'){leaveMultiplayerToMenu(true);return}saveCurrentMatch();document.querySelector('#game').hidden=true;document.querySelector('#game-menu').hidden=false});
function undoLastMove(){const last=history.pop();if(!last)return false;board=last.boardBefore.board;castlingRights=last.boardBefore.rights;enPassantTarget=last.boardBefore.ep;halfmoveClock=last.boardBefore.halfmove;repetitionCounts=last.boardBefore.repetitions;if(last.captured)captured[last.piece[0]].pop();lastMove=history.length?{from:history[history.length-1].from,to:history[history.length-1].to}:null;selected=null;legal=[];pendingPower=null;render();renderLog();renderCaptures();saveCurrentMatch();return true}
powerButton.addEventListener('click',()=>{const power=isTwoPlayerMode()?localPowers[turn]:equippedPower;if(!power)return;if((usedPower[turn][power]||0)>0||gameOver||!canPlayTurn())return;if(power==='time'){showPowerEffect('time',turn);usedPower[turn][power]=3;extraTurn=true;statusEl.textContent=`O tempo parou! ${sideDisplayName(turn)} ganha mais um lance.`}else if(power==='hamon'||power==='killer'){usedPower[turn][power]=3;pendingPower=power;statusEl.textContent=power==='hamon'?'Onda Hamon: escolha um peão inimigo no tabuleiro.':'Killer Queen: escolha uma peça inimiga para explodir.'}else if(power==='arrow'){usedPower[turn][power]=3;if(selected&&type(board[selected[0]][selected[1]])==='p'){showPowerEffect('arrow',turn);board[selected[0]][selected[1]]=turn+'q';halfmoveClock=0;selected=null;legal=[];completeAction();return}pendingPower='arrow';statusEl.textContent='Flecha do Stand: escolha um peão seu no tabuleiro.'}else if(power==='diamond'){const stash=captured[turn==='w'?'b':'w'];pendingRestorePiece=stash[stash.length-1];if(!pendingRestorePiece){statusEl.textContent='Ainda não há peça capturada para restaurar.';return}usedPower[turn][power]=3;pendingPower='diamond';statusEl.textContent=`Crazy Diamond: escolha uma casa vazia para restaurar ${names[type(pendingRestorePiece)]}.`}else{const last=history[history.length-1];if(!last||last.piece[0]===turn||!last.boardBefore){statusEl.textContent='Apagar o Tempo só funciona após um movimento inimigo.';return}usedPower[turn][power]=3;showPowerEffect('crimson',turn);undoLastMove();return}render();saveCurrentMatch()});
document.querySelector('#open-shop-menu').addEventListener('click',openShop);document.querySelector('#open-shop-game').addEventListener('click',openShop);document.querySelector('#close-shop').addEventListener('click',()=>document.querySelector('#shop-dialog').close());
document.querySelector('#tournament-next').addEventListener('click',()=>{const won=tournamentResultWon;tournamentResultWon=false;tournamentResultPending=false;if(won){if(tournamentRound===tournamentOpponents.length-1){tournamentRound=0;tournamentRewarded=false;resetRound();updateOpponent();statusEl.textContent='Torneio concluído! Confira sua recompensa na loja.';saveCurrentMatch();return}tournamentRound++}resetRound();updateOpponent();saveCurrentMatch()});
document.querySelector('#reset').addEventListener('click',()=>{tournamentResultWon=false;tournamentResultPending=false;if(mode==='tournament')tournamentRound=0;resetRound();updateOpponent();saveCurrentMatch()});
document.querySelectorAll('.promotion-options button').forEach(button=>button.addEventListener('click',()=>{if(!promotionPending)return;const {from,to}=promotionPending;promotionPending=null;const dialog=document.querySelector('#promotion-dialog');if(dialog.close)dialog.close();else dialog.removeAttribute('open');makeMove(from,to,button.dataset.piece)}));
document.querySelector('#claim-draw').addEventListener('click',()=>{const key=positionKey();if(repetitionCounts[key]>=3||halfmoveClock>=100){gameOver=true;statusEl.textContent=repetitionCounts[key]>=3?'EMPATE REIVINDICADO POR REPETIÇÃO':'EMPATE REIVINDICADO PELA REGRA DOS 50 LANCES';document.querySelector('#claim-draw').hidden=true;if(mode==='tournament'){document.querySelector('#tournament-next').hidden=false;document.querySelector('#tournament-next').textContent='TENTAR ESTA FASE DE NOVO'}render();showGameResult(statusEl.textContent)}});
document.querySelector('#shop-dialog').addEventListener('click',event=>{if(event.target.id==='shop-dialog')event.target.close()});

window.addEventListener('pagehide',()=>{stopPowerSounds();closeMultiplayerPeer()});
